#!/usr/bin/env python3
from pathlib import Path
import cyclopts

# Create a sample pyproject.toml if it doesn't exist
def setup_config():
    config_file = Path("pyproject.toml")
    if not config_file.exists():
        config_file.write_text("""[tool.mycli]
name = "DefaultName"
count = 3
verbose = false
greet_format = "Hello, {name}!"
""")

setup_config()

# Create the App with TOML configuration support
app = cyclopts.App(
    name="mycli",
    config_search_paths=["pyproject.toml"],
)

@app.default
def greet(
    name: str = "World",
    count: int = 1,
    verbose: bool = False,
    greet_format: str = "Hello, {name}!",
) -> None:
    """
    Greet someone multiple times.

    Defaults are read from [tool.mycli] in pyproject.toml.
    Command-line arguments override config file values.
    """
    for i in range(count):
        message = greet_format.format(name=name)
        if verbose:
            print(f"[{i+1}/{count}] {message}")
        else:
            print(message)

@app.command
def config() -> None:
    """Display the current configuration."""
    config_file = Path("pyproject.toml")
    if config_file.exists():
        print("Current pyproject.toml [tool.mycli] section:")
        print(config_file.read_text())
    else:
        print("No pyproject.toml found.")

if __name__ == "__main__":
    app()

